draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw banana
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t)*70, H/2 + Math.sin(t)*20, 40, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure eating
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 20, 0, 2*Math.PI); // head
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 80);
  ctx.lineTo(W/2, H/2 - 50); // body
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 - 30, H/2 - 20); // arm
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 + 30, H/2 - 20); // arm
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 + 20); // leg
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2 - 20, H/2 + 20); // leg
  ctx.stroke();

  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Eat healthy!', W/2, H - 20);

  ctx.restore();
}
